 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next((r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0), None)
    if sep is None:
        raise ValueError('horizontal separators not found')
    cell_h = sep
    sep_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] and grid[r][c] != 0 for r in range(h))]
    # In these puzzles, separator columns align with separator rows.
    sep_color = grid[sep][0]
    sep_cols = [c for c in range(w) if all(grid[r][c] == sep_color for r in range(h))]
    cell_w = sep_cols[0]
    row_starts = list(range(0, h, cell_h + 1))
    col_starts = list(range(0, w, cell_w + 1))
    # Find the non-background design in any panel other than the color-key column.
    pattern = None
    for rs in row_starts:
        for cs in col_starts[1:]:
            if rs + cell_h > h or cs + cell_w > w:
                continue
            mask = [[grid[rs+i][cs+j] != 0 for j in range(cell_w)] for i in range(cell_h)]
            if any(any(row) for row in mask):
                pattern = mask
                break
        if pattern is not None:
            break
    if pattern is None:
        raise ValueError('design pattern not found')
    out = [[0 for _ in range(w)] for _ in range(h)]
    # Keep the grid's separating lines intact.
    for r in range(h):
        if r not in row_starts:
            out[r] = list(grid[r])
    for c in sep_cols:
        for r in range(h):
            out[r][c] = sep_color
    for ri, rs in enumerate(row_starts):
        if rs + cell_h > h:
            continue
        key = next((grid[rs+i][j] for i in range(cell_h) for j in range(cell_w) if grid[rs+i][j] not in (0, sep_color)), None)
        if key is None:
            continue
        for cs in col_starts:
            if cs + cell_w > w:
                continue
            for i in range(cell_h):
                for j in range(cell_w):
                    if pattern[i][j]:
                        out[rs+i][cs+j] = key
    return out
